/* =============================================================================
   REG-00 · FSR — Formulario de Solicitud de Registro (Módulo 01 · Ruta 00.2)
   =============================================================================
   Pantalla completa SIN shell. Su raíz es hija directa de #root
   (`position: fixed; inset: 0`, sin overflow): por eso el scroll vive aquí,
   con `height: 100%` + `overflow-y: auto`. Sin esas dos líneas, un formulario
   más alto que la ventana se recortaría sin barra.

   Todo el color sale de tokens.css: ningún hex, ningún rgb().
   ========================================================================== */

.page {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow-y: auto;
  background: var(--bw-deep-steel);
}

/* ── Barra de marca ──────────────────────────────────────────────────────── */

.brandBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  height: var(--bw-h-brand);
  padding: var(--bw-pad-brand);
  background: var(--bw-deep-steel-darkest);
  color: var(--bw-on-dark-brand);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-brand);
  font-weight: 400;
  letter-spacing: var(--bw-ls-brand);
  text-transform: uppercase;
}

/* ── Cabecera mínima: solo el logo ───────────────────────────────────────── */

.header {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  height: 46px;
  background: var(--bw-deep-steel-darkest);
  border-bottom: 0.5px solid var(--bw-on-dark-hairline);
}

.logo {
  display: block;
  height: var(--bw-w-logo-height);
  width: auto;
}

/* ── Cuerpo centrado ─────────────────────────────────────────────────────── */

.body {
  flex: 1 0 auto;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 40px 24px 48px;
}

.card {
  width: 100%;
  max-width: 560px;
  /* El sistema no define un blanco puro: `--bw-warm-cream` es el token de
     superficie clara más cercano a la tarjeta blanca del HTML aprobado. */
  background: var(--bw-warm-cream);
  border-radius: 6px;
  padding: 40px 44px 36px;
  box-shadow: 0 4px 32px var(--bw-sidebar-overlay);
}

.eyebrow {
  margin-bottom: 10px;
  font-family: var(--bw-font-title);
  /* F-209: 11 px del HTML aprobado, no `--bw-size-eyebrow` (14 px). */
  font-size: 11px;
  font-weight: 600;
  letter-spacing: var(--bw-ls-eyebrow);
  text-transform: uppercase;
  color: var(--bw-brass);
}

.title {
  margin-bottom: 8px;
  font-family: var(--bw-font-title);
  /* F-209: 22 px del HTML aprobado, no `--bw-size-title` (28 px). */
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.3px;
  line-height: 1.25;
  color: var(--bw-deep-steel);
}

.subtitle {
  margin-bottom: 28px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-steel-mist);
}

/* ── Formulario ──────────────────────────────────────────────────────────── */

.form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.label {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: var(--bw-size-label);
  font-weight: 500;
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-deep-steel);
}

.required {
  color: var(--bw-calibration-blue);
  font-size: 13px;
  line-height: 1;
}

.input,
.select {
  width: 100%;
  padding: var(--bw-pad-input);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  background: var(--bw-warm-cream);
  color: var(--bw-input-text);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.input::placeholder {
  color: var(--bw-input-placeholder);
}

.input:focus,
.select:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

/* El chevron del `select` es el nativo: el del HTML aprobado era un data-URI
   SVG con un color literal dentro, y aquí ningún color se escribe a mano. */
.select {
  cursor: pointer;
}

.error {
  margin-top: 1px;
  font-size: 11px;
  color: var(--bw-error-text);
}

.inputError {
  border-color: var(--bw-error-text);
  box-shadow: 0 0 0 3px var(--bw-sensitive-bg);
}

/* ── Envío ───────────────────────────────────────────────────────────────── */

.submit {
  width: 100%;
  margin-top: 6px;
  padding: 12px 20px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  /* Texto casi blanco: `--bw-warm-cream` es el token claro más cercano. */
  color: var(--bw-warm-cream);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, opacity 0.15s;
}

/* Deshabilitado = el mismo azul, atenuado (el HTML aprobado lo pinta al 32%). */
.submit:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.submit:not(:disabled):hover {
  background: var(--bw-primary-dark);
}

.alert {
  padding: 10px 12px;
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  background: var(--bw-sensitive-bg);
  color: var(--bw-error-text);
  font-size: 12px;
  line-height: 1.5;
}

/* ── Enlace de invitación (Ruta 00.1) ────────────────────────────────────── */

.invitation {
  display: block;
  margin: 18px auto 0;
  padding: 0;
  border: none;
  background: none;
  color: var(--bw-brass);
  font-family: var(--bw-font-body);
  font-size: 12px;
  font-weight: 500;
  text-align: center;
  cursor: pointer;
  transition: color 0.12s;
}

.invitation:hover {
  text-decoration: underline;
}

import { useState } from 'react';
import type { ChangeEvent, FormEvent } from 'react';
import {
  ACCESS_REQUEST_FIELDS,
  COUNTRY_OPTIONS,
  EMPTY_ACCESS_REQUEST,
  FIELD_META,
  blurError,
  canSubmitAccessRequest,
  submitAccessRequest,
} from '../../lib/access-request';
import type { AccessRequestField, AccessRequestForm, SubmittedAccessRequest } from '../../lib/access-request';
import styles from './AccessRequest.module.css';

/**
 * REG-00 — FSR · Formulario de Solicitud de Registro (Módulo 01, Ruta 00.2).
 *
 * Página completa SIN shell: es lo que ve quien no tiene sesión ni enlace de
 * invitación, así que no hay sidebar, ni top nav, ni VERA (el asistente solo
 * responde con sesión). Solo barra de marca, cabecera mínima con el logo y la
 * tarjeta blanca centrada.
 *
 * Aquí vive TODO el estado del formulario (los seis valores, los errores ya
 * visibles, si está enviando y el error de envío) y aquí está la ÚNICA llamada a
 * la red: `submitAccessRequest`, una vez por intento. Nada de validación propia:
 * la verdad es `app/src/lib/access-request.ts`.
 *
 * El error de un campo se enseña SOLO al salir de él (`onBlur` → `blurError`), que
 * es la regla del HTML aprobado; como el botón está deshabilitado hasta que los
 * seis valen, no hay un "intentar enviar" que pueda sembrar errores de golpe.
 */

/** Un mensaje de error visible por campo; `null` = ese campo no se queja. */
type FieldErrors = Record<AccessRequestField, string | null>;

const NO_ERRORS: FieldErrors = {
  email: null,
  fullName: null,
  orgName: null,
  country: null,
  phone: null,
  website: null,
};

/** El `type` del `<input>` de cada campo (`country` es un `<select>`: no se usa). */
const INPUT_TYPES: Record<AccessRequestField, 'email' | 'text' | 'url'> = {
  email: 'email',
  fullName: 'text',
  orgName: 'text',
  country: 'text',
  phone: 'text',
  website: 'url',
};

/** El `autocomplete` del HTML aprobado, campo a campo. */
const AUTOCOMPLETE: Record<AccessRequestField, string> = {
  email: 'email',
  fullName: 'name',
  orgName: 'organization',
  country: 'country',
  phone: 'tel',
  website: 'url',
};

export function AccessRequest({
  onSubmitted,
  onHaveInvitation,
}: {
  onSubmitted: (request: SubmittedAccessRequest) => void;
  onHaveInvitation: () => void;
}) {
  const [form, setForm] = useState<AccessRequestForm>(EMPTY_ACCESS_REQUEST);
  const [errors, setErrors] = useState<FieldErrors>(NO_ERRORS);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const handleChange =
    (field: AccessRequestField) => (event: ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
      const { value } = event.target;
      setForm((previous) => ({ ...previous, [field]: value }));
    };

  const handleBlur = (field: AccessRequestField) => () => {
    setErrors((previous) => ({ ...previous, [field]: blurError(field, form[field]) }));
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    // Intro dentro de un campo también pasa por aquí: se envía solo si todo vale
    // y no hay ya un envío en vuelo.
    if (submitting || !canSubmitAccessRequest(form)) return;

    setSubmitting(true);
    // Un reintento empieza limpio: el alert del intento anterior se borra.
    setSubmitError(null);
    try {
      const result = await submitAccessRequest(form);
      onSubmitted(result);
    } catch (error) {
      setSubmitError(error instanceof Error ? error.message : 'No se pudo enviar la solicitud.');
    } finally {
      setSubmitting(false);
    }
  };

  const submitDisabled = submitting || !canSubmitAccessRequest(form);

  return (
    <main className={styles.page}>
      <div className={styles.brandBar}>
        <div>ZERO KNOWLEDGE ARCHITECTURE · CRYPTOGRAPHIC SECURITY</div>
        <div>CONNECT · TRADE · SECURE</div>
        <div>INDUSTRIAL INTELLIGENCE NETWORK</div>
      </div>

      {/* Cabecera mínima: solo el logo. Sin menú, sin navegación, sin VERA. */}
      <header className={styles.header}>
        <img className={styles.logo} src="/intentologo.png" alt="Bearingworld.io" />
      </header>

      <div className={styles.body}>
        <div className={styles.card}>
          <p className={styles.eyebrow}>Módulo 01 · Onboarding</p>
          <h1 className={styles.title}>Solicita acceso a Bearingworld.io</h1>
          <p className={styles.subtitle}>
            Nuestro equipo revisará tu solicitud y te contactará en un plazo máximo de 48 horas.
          </p>

          <form className={styles.form} noValidate onSubmit={handleSubmit}>
            {ACCESS_REQUEST_FIELDS.map((field) => {
              const meta = FIELD_META[field];
              const id = `access-request-${field}`;
              const errorId = `${id}-error`;
              const error = errors[field];

              return (
                <div key={field} className={styles.field}>
                  <label className={styles.label} htmlFor={id}>
                    {meta.label}
                    <span className={styles.required} aria-hidden="true">
                      *
                    </span>
                  </label>
                  {field === 'country' ? (
                    <select
                      id={id}
                      name={field}
                      className={error !== null ? `${styles.select} ${styles.inputError}` : styles.select}
                      autoComplete={AUTOCOMPLETE[field]}
                      value={form[field]}
                      onChange={handleChange(field)}
                      onBlur={handleBlur(field)}
                      aria-invalid={error !== null ? true : undefined}
                      aria-describedby={error !== null ? errorId : undefined}
                    >
                      <option value="" disabled>
                        Selecciona un país
                      </option>
                      {COUNTRY_OPTIONS.map(([code, text]) => (
                        <option key={code} value={code}>
                          {text}
                        </option>
                      ))}
                    </select>
                  ) : (
                    <input
                      id={id}
                      name={field}
                      className={error !== null ? `${styles.input} ${styles.inputError}` : styles.input}
                      type={INPUT_TYPES[field]}
                      placeholder={meta.placeholder}
                      maxLength={meta.maxLength}
                      autoComplete={AUTOCOMPLETE[field]}
                      value={form[field]}
                      onChange={handleChange(field)}
                      onBlur={handleBlur(field)}
                      aria-invalid={error !== null ? true : undefined}
                      aria-describedby={error !== null ? errorId : undefined}
                    />
                  )}
                  {error !== null && (
                    <span id={errorId} className={styles.error}>
                      {error}
                    </span>
                  )}
                </div>
              );
            })}

            {submitError !== null && (
              <p className={styles.alert} role="alert">
                {submitError}
              </p>
            )}

            <button type="submit" className={styles.submit} disabled={submitDisabled}>
              Enviar solicitud
            </button>
          </form>

          {/* Único cruce visible hacia la Ruta 00.1. La validación del token
              (REG-01) no existe todavía: solo se avisa al wiring. */}
          <button type="button" className={styles.invitation} onClick={onHaveInvitation}>
            ¿Tienes un enlace de invitación? Accede directamente →
          </button>
        </div>
      </div>
    </main>
  );
}
